import{Fragment as n,jsx as e,jsxs as o}from"wompo/jsx-runtime";import{defineWompo as a}from"wompo";import i from"../../../utils/getPageLayout.js";import{Link as t}from"wompo-router";const l={title:"Hooks",description:"What are hooks: how and when to use them.",sections:[{title:"What are hooks?",id:"what-are-hooks",content:o(n,{children:[o("p",{children:['Hooks are helper functions that let you add specific functionalities in your Wompo components. This functions will "hook" into the component so that they have access to the whole HTML instance and operate adding functionalities to it. More specifically, they allow to:',o("ul",{children:[e("li",{children:"Make your component dynamic"}),e("li",{children:"Create callbacks that will be executed on specific cases"}),e("li",{children:"Keep a variable's value stable across renders"}),o("li",{children:["Get a specific ",e("b",{children:"Context"})]}),e("li",{children:"Optimize performances by avoiding useless re-renderings"})]}),"Hooks work like ",e("b",{children:"import statements"})," inside a component. This implies that:",o("ol",{children:[o("li",{children:["Like import statements, they ",e("b",{children:"must"})," be declared on top of the component, in the first lines, before any operation is performed."]}),e("li",{children:"They cannot be conditional or executed inside loops."})]}),"If these conditions are not respected, the component might have unexpected behaviors."]}),o("p",{children:["Wompo offers a good variety of hooks, but you are also completely free to create your own very easily.",e("br",{})]})]})},{title:"State hooks",id:"state-hooks",content:e(n,{children:o("p",{children:["State hooks are what allow to make a component dynamic and cause a re-render of it, so that you can see visual updates in your component. To do that, Wompo offers the following hooks:",o("ul",{children:[o("li",{children:[e(t,{to:"useState",children:"useState"})," - Probably the most common hook you will use: creates a stateful variable and a setter function that will cause a re-render of the component when called (if the new value differs from the old one)."]}),o("li",{children:[e(t,{to:"useReducer",children:"useReducer"})," - For ",e("b",{children:"Redux"})," fans. This hook allows to elegantly handle the state of a component using a ",e("b",{children:"reducer"})," to handle all the operations to alter the state and a ",e("b",{children:"dispatch"})," function to set the new state."]})]})]})})},{title:"Effect hooks",id:"effect-hooks",content:e(n,{children:o("p",{children:["Effect hooks are what allows to execute a specific ",e("b",{children:"callback"})," when one of your",e("b",{children:"dependencies"})," changes, or simply on the first (or on every) render. This dependencies are simply an array of values. The effect hooks are:",o("ul",{children:[o("li",{children:[e(t,{to:"useEffect",children:"useEffect"})," - After ",e("b",{children:"useState"}),", the probably second most common hook you will use: will execute the callback after a render if any of its dependencies changed. The callback will be executed ",e("b",{children:"Asynchronously"}),"."]}),o("li",{children:[e(t,{to:"useLayoutEffect",children:"useLayoutEffect"})," - It's the same as the"," ",e("b",{children:"useEffect"})," hook. The only difference is that the callback is executed"," ",e("b",{children:"Synchronously"})," immediately after a render, before you can see visual changes. The ",e("i",{children:"useEffect"})," hook is preferred, because it'll not saturate the stack."]})]})]})})},{title:"Performance hooks",id:"performance-hooks",content:e(n,{children:o("p",{children:["Performance hooks let you skip useless operations across renders, or keep a value stable between renders so it's not re-initialized every time, allowing to optimize the component by avoiding unnecessary re-renderings.",e("br",{}),"Performance hooks are:",o("ul",{children:[o("li",{children:[e(t,{to:"useRef",children:"useRef"})," - It'll keep a value stable across renders, by always returning the last saved value. It can optionally also be used to reference a node in the DOM."]}),o("li",{children:[e(t,{to:"useCallback",children:"useCallback"})," - The useCallback hook will take a function and save it so that it's not re-created on every render. This is useful if you're using a function as an attribute value of some other components, because the attribute will always have the same value (remember that in Javascript two functions are never equal, unless a function is compared to itself)."]}),o("li",{children:[e(t,{to:"useMemo",children:"useMemo"})," - This hook will let you execute a callback function and return its result only when a dependency changes, instead of on every render."]})]})]})})},{title:"Context hooks",id:"context-hooks",content:e(n,{children:o("p",{children:["A Context hook will let you ",e("b",{children:"obtain a value provided by another element"}),", more specifically, a",e("code",{children:"Context.Provider"})," element. There is only one context hook:",e("ul",{children:o("li",{children:[e(t,{to:"useContext",children:"useContext"})," - Will return the value provided by the closest parent context provider of the specified context. If there is not one, the default value of the context will be returned. The component that uses this hook will automatically re-render whenever the value provided by the provider changes."]})})]})})},{title:"Helper hooks",id:"helper-hooks",content:e(n,{children:o("p",{children:["Helper hooks are simple hooks that solve common problems. The currently available helper hooks are:",o("ul",{children:[o("li",{children:[e(t,{to:"useId",children:"useId"})," - Will return a unique string in the format"," ",e("code",{children:":w<number>:"}),". The ID will not change on every re-render. This is useful when you want to use IDs for node elements inside of a component. Common use cases are for inputs, labels, and accessibility."]}),o("li",{children:[e(t,{to:"useExposed",children:"useExposed"})," - The useExposed hook will let you expose some values and/or functions in the comonent's instance of the DOM. This allows, for example, to select a DOM node and call a method on it. Can be useful to"," ",e("b",{children:"Expose state"}),". Commonly used in combination with the ",e("i",{children:"useRef"})," hook."]}),o("li",{children:[e(t,{to:"useAsync",children:"useAsync"})," - This hook will take care of asynchronous operations in the component by executing a callback on first render and when one of its dependencies changes. This hooks integrates with the"," ",e("b",{children:e("i",{children:"Suspense"})})," ","component, allowing to easily handle the loading state of the component."]}),o("li",{children:[e(t,{to:"useHook",children:"useHook"})," - The useHook is a special hook used to create your own advanced hooks. Should only be used if the current hooks are not enough to satisfy your needs."]})]})]})})}]};export default function s(){return i(l)}a(s,{name:"hooks-page"});
